import json,subprocess
with open('/proc/meminfo') as f:
 m={l.split(':')[0]:int(l.split()[1]) for l in f if l.split(':')[0] in ('MemTotal','MemAvailable','SwapTotal','SwapFree')}
print(json.dumps({'memoryKiB':m,'containerMemory':subprocess.check_output(['docker','stats','--no-stream','--format','{{.Name}} {{.MemUsage}}'],universal_newlines=True).splitlines()}))

api=subprocess.check_output(['docker','ps','-q','--filter','label=com.docker.compose.project=researchhub-backend','--filter','label=com.docker.compose.service=researchhub-api'],universal_newlines=True).strip()
assert len(api.splitlines())==1
node="import {createHubDefaultSkills} from './server/ai-agent/default-skills.mjs';\nimport {createHash} from 'node:crypto';\nimport {loadSkillCatalog} from './server/ai-agent/skill-catalog.mjs';\nasync function check(tx,c,load,tenant) {\n const session=await tx.session.findFirst({where:{id:'cmwreeddi0009qr07og2z3rck',tenantId:tenant},select:{accountId:true,agentId:true,studyGroupId:true,researchProjectId:true}});\n if(!session)return {sessionFound:false};\n const account=await tx.account.findFirst({where:{id:session.accountId,tenantId:tenant},select:{authVersion:true}});\n const model=await tx.agentConfig.findFirst({where:{tenantId:tenant,agentId:session.agentId,active:true,archivedAt:null},orderBy:{version:'desc'},select:{model:true,tools:true}});\n let route;\n try {route=await load('common/model-route-resolver','resolveConfiguredDeepSeekModelRoute')(tx,tenant,model.model);}catch{}\n let skillResult;\n try {\n const defaults=createHubDefaultSkills({scope:c.scope,tenantId:tenant,agentId:session.agentId,catalog:await loadSkillCatalog(process.cwd()),transaction:fn=>fn(tx),lockAuthorization:load('common/worker-publication','lockAuthorizationMutation'),resolveEffectiveSkillCatalog:load('agents/effective-skills-policy','resolveEffectiveSkillCatalog')});\n const result=await defaults.listInTransaction(tx,{tenantId:tenant,accountId:session.accountId,authVersion:account.authVersion,studyGroupId:session.studyGroupId,researchProjectId:session.researchProjectId});\n skillResult={effectiveCount:result.items.length,attachmentSkill:result.items.some(x=>x.key==='doubao-medical-literature-interpretation')};\n } catch(e) {skillResult={error:e.code??e.name};}\n const catalog=await loadSkillCatalog(process.cwd());\n const configured=await tx.skillAssignment.findMany({where:{tenantId:tenant,agentId:session.agentId,scopeKey:{in:['*',session.accountId]},skill:{status:'published'}},include:{skill:true}});\n const mismatches=configured.flatMap(row=>{\n const skill=row.skill, entry=catalog.skills.find(e=>e.key===skill.key);\n if(!entry)return [];\n const expectedId='hub-skill-'+createHash('sha256').update([tenant,session.agentId,skill.key,'1'].join(':')).digest('hex').slice(0,32);\n if(skill.id!==expectedId)return [];\n return [{key:skill.key,reviewerPresent:Boolean(skill.reviewedBy),snapshotMatch:skill.backend?.sourceSnapshotHash===entry.snapshotHash,pathMatch:skill.backend?.sourcePath===entry.sourcePath,toolsMatch:JSON.stringify(skill.ioContract?.requiredTools)===JSON.stringify(entry.requiredTools),adaptationMatch:JSON.stringify(skill.rules?.adaptation)===JSON.stringify(entry.adaptation),rightsMatch:skill.rules?.sourceRights===entry.rights.status}];\n });\n return {sessionFound:true,routePro:route?.model==='deepseek-v4-pro',routeProvider:route?.provider,routeCredentialPresent:Boolean(route&&process.env[route.secretRef||'DEEPSEEK_API_KEY']),tools:{read:model?.tools?.includes('file.read'),search:model?.tools?.includes('knowledge.search')},skillResult,mismatches};\n}\n\nimport assert from'node:assert/strict';import{readResearchRuntimeConfig}from'./server/research-runtime/config.mjs';import{runtimeDependencies}from'./server/research-runtime/dependencies.mjs';import{bindRuntimeTransactions,withDeploymentTransaction}from'./server/database/transactions.mjs';let prisma;try{const c=readResearchRuntimeConfig(process.env),tenant='rh-kb-local-b0e2af9d-tenant';assert(c.identity.database==='researchhub'&&c.identity.tenantId===tenant);const{load}=runtimeDependencies(c.core);prisma=new(load('prisma/prisma.service','PrismaService'))();await prisma.app.$connect();await prisma.elevated.$connect();const env=bindRuntimeTransactions({prisma,expected:c.identity});const result=await withDeploymentTransaction(env,'direct',async tx=>{return {configuration:await check(tx,c,load,tenant),now:new Date().toISOString(),workers:c.scope.enabledWorkerKinds,materials:await tx.$queryRawUnsafe(`SELECT m.state, m.deleted_at IS NOT NULL AS removed, t.status, t.stage, t.progress, t.\"errorCode\", t.\"safetyLevel\", d.status AS doc_status, d.reviewed FROM rh_ai.session_materials m LEFT JOIN public.knowledge_import_task t ON t.id=m.import_task_id LEFT JOIN public.knowledge_doc d ON d.id=t.\"docId\" WHERE m.session_id=$1 AND m.tenant_id=$2 ORDER BY m.created_at DESC LIMIT 12`,'cmwreeddi0009qr07og2z3rck',tenant)};},{readOnly:true});console.log(JSON.stringify({status:'hub-production-inspected',databaseWrites:0,modelCalls:0,runtime:c.executionProfile,...result}));}catch(e){console.log(JSON.stringify({status:'stopped',code:'INSPECT_CAPABILITY_FAILED'}));process.exitCode=1}finally{await prisma?.app?.$disconnect();await prisma?.elevated?.$disconnect()}\n"
print(subprocess.check_output(['docker','exec',api,'node','--input-type=module','-e',node],universal_newlines=True))
